// src/components/Sidebar.jsx
import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './Sidebar.css';

const Sidebar = ({ usuario, admin, onLogout }) => {
  const [open, setOpen] = useState(false);

  const toggleSidebar = () => {
    setOpen(!open);
  };

  const closeSidebar = () => {
    setOpen(false);
  };

  return (
    <>
      <button className="btn btn-secondary m-3" onClick={toggleSidebar}>
        ☰ Menú
      </button>

      <div className={`sidebar ${open ? 'open' : ''}`}>
        <button className="close-btn" onClick={closeSidebar}>×</button>

        {/* Siempre visible */}
        <Link to="/" onClick={closeSidebar}>Inicio</Link>

        {/* Si no hay usuario ni admin */}
        {!usuario && !admin && (
          <>
            {/*<Link to="/registro" onClick={closeSidebar}>Registro</Link>*/}
            <Link to="/acceder" onClick={closeSidebar}>Acceder</Link>
            {/*<Link to="/talleres" onClick={closeSidebar}>Workshops & Challenge</Link>*/}
          </>
        )}

        {/* Si hay usuario logueado */}
        {usuario && (
          <>
            <Link to="/perfil" onClick={closeSidebar}>Perfil</Link>
            <Link to="/editarPerfil" onClick={closeSidebar}>Editar usuario</Link>
            <Link to="/competencia" onClick={closeSidebar}>Competencia</Link>
            <Link to="/cambiarPassword" onClick={closeSidebar}>Cambiar contraseña</Link>
            <a href="#" className="text-white" onClick={() => { onLogout(); closeSidebar(); }}>Cerrar sesión</a>
          </>
        )}

        {/* Si hay administrador logueado */}
        {admin && (
          <>
            <Link to="/admin" onClick={closeSidebar}>Panel Admin</Link>
            <Link to="/categorias" onClick={closeSidebar}>Categorías</Link>
            <Link to="/competidores" onClick={closeSidebar}>Competidores</Link>
            <Link to="/usuarios" onClick={closeSidebar}>Usuarios</Link>
            <Link to="/horario" onClick={closeSidebar}>Horario</Link>
            <Link to="/control" onClick={closeSidebar}>Control</Link>
            <Link to="/calificaciones" onClick={closeSidebar}>Calificaciones</Link>
            <a href="#" className="text-white" onClick={() => { onLogout(); closeSidebar(); }}>Cerrar sesión</a>
          </>
        )}
      </div>
    </>
  );
};

export default Sidebar;
