
import React, { useEffect, useState, useRef } from 'react';
import {
  ref,
  push,
  get,
  child,
  update,
  remove,
  onValue,
} from 'firebase/database';
import {
  ref as storageRef,
  uploadBytes,
  getDownloadURL,
  deleteObject,
} from 'firebase/storage';
import { database, storage } from '../firebase/firebase';
import { FaPlay, FaPause } from 'react-icons/fa';
import { getAuth, onAuthStateChanged } from 'firebase/auth';

const AgregarCompetidor = () => {
  const [categorias, setCategorias] = useState([]);
  const [nombre, setNombre] = useState('');
  const [compania, setCompania] = useState('');
  const [categoriaSeleccionada, setCategoriaSeleccionada] = useState('');
  const [archivoMusica, setArchivoMusica] = useState(null);
  const [modoEdicion, setModoEdicion] = useState(false);
  const [idEdicion, setIdEdicion] = useState(null);
  const [competidores, setCompetidores] = useState([]);
  const [cargando, setCargando] = useState(false);
  const [usuario, setUsuario] = useState(null);
  const [diaActual, setDiaActual] = useState('');

  // Estados para control de audio
  const [audioEnReproduccion, setAudioEnReproduccion] = useState(null);
  const [tiempoRestante, setTiempoRestante] = useState(0);
  const [progreso, setProgreso] = useState(0);
  const audioRef = useRef(null);
  const intervalRef = useRef(null);
  const auth = getAuth();

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      if (user) {
        setUsuario(user.uid);
        cargarCompetidores(user.uid);
      } else {
        setUsuario(null);
        setCompetidores([]);
      }
    });

    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const adminRef = ref(database, 'adminMinutoAMinuto');
    const categoriasRef = ref(database, 'categorias');

    const unsubscribeAdmin = onValue(adminRef, (adminSnap) => {
      if (adminSnap.exists()) {
        const adminData = adminSnap.val();
        const dia = adminData.dia?.toLowerCase() || '';

        setDiaActual(dia);

        get(categoriasRef)
          .then((snapshot) => {
            if (snapshot.exists()) {
              const data = snapshot.val();

              const lista = Object.entries(data)
                .map(([id, info]) => ({ id, ...info }))
                .filter((cat) => cat.dia?.toLowerCase() === dia)
                .sort((a, b) => a.orden - b.orden);

              setCategorias(lista);
            } else {
              setCategorias([]);
            }
          })
          .catch((error) => {
            console.error('Error al obtener categorías:', error);
            setCategorias([]);
          });
      } else {
        setCategorias([]);
      }
    });

    return () => unsubscribeAdmin();
  }, []);

  const cargarCompetidores = async (uid) => {
    const snapshot = await get(child(ref(database), 'competidores'));

    if (snapshot.exists()) {
      const data = snapshot.val();
      const lista = [];

      for (const categoria in data) {
        const competidoresCat = data[categoria];

        for (const id in competidoresCat) {
          const competidor = competidoresCat[id];

          if (competidor.usuarioId === uid) {
            lista.push({ id, categoria, ...competidor });
          }
        }
      }

      setCompetidores(lista);
    } else {
      setCompetidores([]);
    }
  };

  const sanitizarTexto = (texto) =>
    texto
      .trim()
      .toLowerCase()
      .replace(/\s+/g, '_')
      .replace(/[^a-z0-9_]/g, '');

  const manejarEditar = (competidor) => {
    setModoEdicion(true);
    setIdEdicion(competidor.id);
    setNombre(competidor.nombre);
    setCompania(competidor.compania);
    setCategoriaSeleccionada(competidor.categoria);
    setArchivoMusica(null);
  };

  const manejarEliminar = async (competidor) => {
    if (!window.confirm(`¿Eliminar competidor ${competidor.nombre}?`)) {
      return;
    }

    if (
      competidor.musicaURL &&
      audioEnReproduccion?.src === competidor.musicaURL
    ) {
      pausarMusica();
    }

    try {
      if (competidor.musicaPath) {
        const musicaRef = storageRef(storage, competidor.musicaPath);

        await deleteObject(musicaRef).catch(() => {
          console.warn('Archivo de música no encontrado o ya eliminado.');
        });
      }

      await remove(
        ref(
          database,
          `competidores/${sanitizarTexto(competidor.categoria)}/${competidor.id}`
        )
      );

      alert('Competidor eliminado correctamente.');
      await cargarCompetidores(usuario);
    } catch (error) {
      console.error('Error eliminando competidor:', error);
      alert('Error al eliminar competidor.');
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setCargando(true);

    if (!usuario) {
      alert('Debes iniciar sesión para agregar competidores.');
      setCargando(false);
      return;
    }

    if (
      !nombre.trim() ||
      !compania.trim() ||
      !categoriaSeleccionada
    ) {
      alert('Por favor completa el nombre, la compañía y la categoría.');
      setCargando(false);
      return;
    }

    try {
      if (modoEdicion && idEdicion) {
        // Buscar al competidor original en todas las categorías.
        let categoriaOriginal = null;
        let snapshotOriginal = null;

        const competidoresSnapshot = await get(
          child(ref(database), 'competidores')
        );

        if (competidoresSnapshot.exists()) {
          const data = competidoresSnapshot.val();

          for (const cat in data) {
            if (data[cat]?.[idEdicion]) {
              categoriaOriginal = cat;
              snapshotOriginal = data[cat][idEdicion];
              break;
            }
          }
        }

        if (!categoriaOriginal) {
          alert('Error: competidor a editar no encontrado.');
          setCargando(false);
          return;
        }

        const actualizacion = {
          nombre: nombre.trim(),
          compania: compania.trim(),
          categoria: categoriaSeleccionada,
          usuarioId: usuario,
          fechaInscripcion:
            snapshotOriginal.fechaInscripcion ||
            new Date().toISOString(),
        };

        // Si se selecciona música nueva, reemplazar la anterior.
        if (archivoMusica) {
          if (snapshotOriginal.musicaPath) {
            const musicaAnteriorRef = storageRef(
              storage,
              snapshotOriginal.musicaPath
            );

            await deleteObject(musicaAnteriorRef).catch(() => {
              console.warn(
                'No se pudo eliminar el archivo anterior de música.'
              );
            });
          }

          const nombreArchivoNuevo = `musica/${sanitizarTexto(
            categoriaSeleccionada
          )}_${sanitizarTexto(nombre)}_${Date.now()}.mp3`;

          const nuevaMusicaRef = storageRef(
            storage,
            nombreArchivoNuevo
          );

          await uploadBytes(nuevaMusicaRef, archivoMusica);

          const nuevaMusicaURL = await getDownloadURL(nuevaMusicaRef);

          actualizacion.musicaURL = nuevaMusicaURL;
          actualizacion.musicaPath = nombreArchivoNuevo;
        } else {
          const categoriaNueva = sanitizarTexto(categoriaSeleccionada);
          const categoriaVieja = sanitizarTexto(categoriaOriginal);

          // Si cambia la categoría y existe música, moverla al nuevo nombre.
          if (
            categoriaNueva !== categoriaVieja &&
            snapshotOriginal.musicaPath &&
            snapshotOriginal.musicaURL
          ) {
            const musicaAnteriorRef = storageRef(
              storage,
              snapshotOriginal.musicaPath
            );

            const extension =
              snapshotOriginal.musicaPath.split('.').pop();

            const nuevoNombreArchivo = `musica/${categoriaNueva}_${sanitizarTexto(
              nombre
            )}_${Date.now()}.${extension}`;

            const nuevaMusicaRef = storageRef(
              storage,
              nuevoNombreArchivo
            );

            const respuesta = await fetch(snapshotOriginal.musicaURL);

            if (!respuesta.ok) {
              throw new Error('No se pudo recuperar la música existente.');
            }

            const musicaBlob = await respuesta.blob();

            await uploadBytes(nuevaMusicaRef, musicaBlob);

            const nuevaURL = await getDownloadURL(nuevaMusicaRef);

            await deleteObject(musicaAnteriorRef).catch(() => {
              console.warn(
                'No se pudo eliminar el archivo anterior de música.'
              );
            });

            actualizacion.musicaURL = nuevaURL;
            actualizacion.musicaPath = nuevoNombreArchivo;
          } else {
            // Si no se seleccionó música nueva, conservar la existente.
            actualizacion.musicaURL =
              snapshotOriginal.musicaURL || null;

            actualizacion.musicaPath =
              snapshotOriginal.musicaPath || null;
          }
        }

        if (
          categoriaOriginal === sanitizarTexto(categoriaSeleccionada)
        ) {
          // La categoría no cambió: actualizar el registro existente.
          const competidorRef = ref(
            database,
            `competidores/${categoriaOriginal}/${idEdicion}`
          );

          await update(competidorRef, actualizacion);
        } else {
          // La categoría cambió: mover el registro a la nueva categoría.
          await remove(
            ref(
              database,
              `competidores/${categoriaOriginal}/${idEdicion}`
            )
          );

          const competidorRefNuevo = ref(
            database,
            `competidores/${sanitizarTexto(categoriaSeleccionada)}`
          );

          await push(competidorRefNuevo, {
            ...actualizacion,
            dia: snapshotOriginal.dia || diaActual,
            orden: snapshotOriginal.orden || 1,
          });
        }

        alert('Competidor actualizado correctamente.');
      } else {
        // NUEVO COMPETIDOR: la música es opcional.
        const categoriaSanitizada = sanitizarTexto(
          categoriaSeleccionada
        );

        const competidorRef = ref(
          database,
          `competidores/${categoriaSanitizada}`
        );

        // Obtener competidores de la categoría para calcular el orden del día.
        const competidoresSnapshot = await get(competidorRef);

        let totalCompetidores = 0;

        if (competidoresSnapshot.exists()) {
          const todos = competidoresSnapshot.val();

          const soloDelDia = Object.values(todos).filter(
            (competidor) => competidor.dia === diaActual
          );

          totalCompetidores = soloDelDia.length;
        }

        // Preparar los datos sin exigir música.
        const nuevoCompetidor = {
          nombre: nombre.trim(),
          compania: compania.trim(),
          categoria: categoriaSeleccionada,
          fechaInscripcion: new Date().toISOString(),
          usuarioId: usuario,
          dia: diaActual,
          orden: totalCompetidores + 1,
        };

        // Subir el archivo solamente si se seleccionó uno.
        if (archivoMusica) {
          const nombreArchivo = `musica/${categoriaSanitizada}_${sanitizarTexto(
            nombre
          )}_${Date.now()}.mp3`;

          const musicaRef = storageRef(storage, nombreArchivo);

          await uploadBytes(musicaRef, archivoMusica);

          const musicaURL = await getDownloadURL(musicaRef);

          nuevoCompetidor.musicaURL = musicaURL;
          nuevoCompetidor.musicaPath = nombreArchivo;
        }

        // Registrar al competidor con o sin música.
        await push(competidorRef, nuevoCompetidor);

        alert('Competidor inscrito correctamente.');
      }

      // Limpiar el formulario después de guardar.
      setNombre('');
      setCompania('');
      setCategoriaSeleccionada('');
      setArchivoMusica(null);
      setModoEdicion(false);
      setIdEdicion(null);

      await cargarCompetidores(usuario);
    } catch (error) {
      console.error('Error al guardar o actualizar:', error);
      alert('Ocurrió un error al guardar la información.');
    } finally {
      setCargando(false);
    }
  };

  const reproducirMusica = (url) => {
    if (!url) {
      alert('Este competidor no tiene música asignada.');
      return;
    }

    if (audioRef.current) {
      if (audioRef.current.src === url) {
        if (audioRef.current.paused) {
          audioRef.current.play();
          setAudioEnReproduccion(audioRef.current);
          iniciarIntervalo();
        } else {
          audioRef.current.pause();
          setAudioEnReproduccion(null);
          limpiarIntervalo();
        }

        return;
      } else {
        audioRef.current.pause();
        limpiarIntervalo();
      }
    }

    const nuevoAudio = new Audio(url);
    audioRef.current = nuevoAudio;

    nuevoAudio.addEventListener('loadedmetadata', () => {
      setTiempoRestante(nuevoAudio.duration);
      setProgreso(0);
    });

    nuevoAudio.play().catch((error) => {
      console.error('Error al reproducir música:', error);
      setAudioEnReproduccion(null);
    });

    setAudioEnReproduccion(nuevoAudio);
    iniciarIntervalo();

    nuevoAudio.addEventListener('ended', () => {
      limpiarIntervalo();
      setAudioEnReproduccion(null);
      setProgreso(0);
      setTiempoRestante(0);
    });
  };

  const iniciarIntervalo = () => {
    limpiarIntervalo();

    intervalRef.current = setInterval(() => {
      if (audioRef.current && !audioRef.current.paused) {
        const restante =
          audioRef.current.duration - audioRef.current.currentTime;

        setTiempoRestante(restante);

        setProgreso(
          (audioRef.current.currentTime / audioRef.current.duration) * 100
        );
      }
    }, 500);
  };

  const limpiarIntervalo = () => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
  };

  const manejarCambioProgreso = (e) => {
    const valor = Number(e.target.value);

    if (audioRef.current && Number.isFinite(audioRef.current.duration)) {
      const nuevoTiempo = (valor / 100) * audioRef.current.duration;

      audioRef.current.currentTime = nuevoTiempo;
      setProgreso(valor);
      setTiempoRestante(audioRef.current.duration - nuevoTiempo);
    }
  };

  useEffect(() => {
    return () => {
      if (audioRef.current) {
        audioRef.current.pause();
      }

      limpiarIntervalo();
    };
  }, []);

  const formatearTiempo = (segundos) => {
    if (!segundos || isNaN(segundos) || !isFinite(segundos)) {
      return '0:00';
    }

    const mins = Math.floor(segundos / 60);
    const seg = Math.floor(segundos % 60);

    return `${mins}:${seg < 10 ? '0' : ''}${seg}`;
  };

  const pausarMusica = () => {
    if (audioRef.current) {
      audioRef.current.pause();
      setAudioEnReproduccion(null);
      limpiarIntervalo();
    }
  };

  return (
    <div className="container mt-4">
      <h3>
        {modoEdicion ? 'Editar Competidor' : 'Inscripción a Competencia'}
      </h3>

      <form onSubmit={handleSubmit}>
        <div className="mb-3">
          <label>Nombre del competidor:</label>
          <input
            type="text"
            className="form-control"
            value={nombre}
            onChange={(e) => setNombre(e.target.value)}
            required
          />
        </div>

        <div className="mb-3">
          <label>Compañía:</label>
          <input
            type="text"
            className="form-control"
            value={compania}
            onChange={(e) => setCompania(e.target.value)}
            required
          />
        </div>

        <div className="mb-3">
          <label>Categoría:</label>
          <select
            className="form-select"
            value={categoriaSeleccionada}
            onChange={(e) => setCategoriaSeleccionada(e.target.value)}
            required
          >
            <option value="">Seleccione una categoría</option>

            {categorias.map((cat) => (
              <option key={cat.id} value={cat.nombre}>
                {cat.orden}. {cat.nombre}
              </option>
            ))}
          </select>
        </div>

        <div className="mb-3">
          <label>Música (archivo .mp3, opcional):</label>
          <input
            type="file"
            className="form-control"
            accept=".mp3,audio/mpeg"
            onChange={(e) =>
              setArchivoMusica(e.target.files?.[0] || null)
            }
          />

          <small className="text-muted">
            Puedes inscribir al competidor sin música y agregarla después.
          </small>
        </div>

        <button
          type="submit"
          className="btn btn-primary"
          disabled={cargando}
        >
          {cargando
            ? 'Guardando...'
            : modoEdicion
              ? 'Actualizar'
              : 'Inscribir'}
        </button>

        {modoEdicion && (
          <button
            type="button"
            className="btn btn-secondary ms-2"
            onClick={() => {
              setNombre('');
              setCompania('');
              setCategoriaSeleccionada('');
              setArchivoMusica(null);
              setModoEdicion(false);
              setIdEdicion(null);
            }}
            disabled={cargando}
          >
            Cancelar
          </button>
        )}
      </form>

      <hr />

      <h4>Competidores inscritos</h4>

      {competidores.length === 0 && (
        <p>No hay competidores inscritos.</p>
      )}

      <div className="table-responsive">
        <table className="table">
          <thead>
            <tr>
              <th>Nombre</th>
              <th>Compañía</th>
              <th>Categoría</th>
              <th>Música</th>
              <th>Acciones</th>
            </tr>
          </thead>

          <tbody>
            {competidores.map((comp) => (
              <tr key={`${comp.categoria}-${comp.id}`}>
                <td>{comp.nombre}</td>
                <td>{comp.compania}</td>
                <td>{comp.categoria}</td>

                <td>
                  {comp.musicaURL ? (
                    <>
                      <button
                        type="button"
                        className="btn btn-outline-primary btn-sm"
                        onClick={() => reproducirMusica(comp.musicaURL)}
                        title={
                          audioEnReproduccion?.src === comp.musicaURL &&
                          audioRef.current &&
                          !audioRef.current.paused
                            ? 'Pausar música'
                            : 'Reproducir música'
                        }
                      >
                        {audioEnReproduccion?.src === comp.musicaURL &&
                        audioRef.current &&
                        !audioRef.current.paused ? (
                          <FaPause />
                        ) : (
                          <FaPlay />
                        )}
                      </button>

                      {audioEnReproduccion?.src === comp.musicaURL && (
                        <>
                          <input
                            type="range"
                            min="0"
                            max="100"
                            value={progreso}
                            onChange={manejarCambioProgreso}
                            style={{
                              width: '100px',
                              marginLeft: '10px',
                            }}
                          />

                          <span style={{ marginLeft: '10px' }}>
                            {formatearTiempo(tiempoRestante)}
                          </span>
                        </>
                      )}
                    </>
                  ) : (
                    <span className="text-muted">Sin música</span>
                  )}
                </td>

                <td>
                  <button
                    type="button"
                    className="btn btn-warning btn-sm me-2"
                    onClick={() => manejarEditar(comp)}
                  >
                    Editar
                  </button>

                  <button
                    type="button"
                    className="btn btn-danger btn-sm"
                    onClick={() => manejarEliminar(comp)}
                  >
                    Eliminar
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default AgregarCompetidor;
