import React, { useEffect, useState } from 'react';
import { ref as dbRef, get } from 'firebase/database';
import { auth, database } from '../firebase/firebase';
import './PerfilUsuario.css';

const PerfilUsuario = ({ onLogout }) => {
  const [usuario, setUsuario] = useState(null);
  const uid = auth.currentUser?.uid || localStorage.getItem('usuarioUID');

  useEffect(() => {
    if (!uid) return;

    const fetchUserData = async () => {
      try {
        const snapshot = await get(dbRef(database, `usuarios/${uid}`));
        if (snapshot.exists()) {
          setUsuario(snapshot.val());
        }
      } catch (error) {
        console.error('Error cargando perfil:', error);
      }
    };

    fetchUserData();
  }, [uid]);

  if (!usuario) return <p>Cargando perfil...</p>;

  return (
    <section className="p-5 text-center bg-white">
      <h2>Perfil del Usuario</h2>
      <img
        src={usuario.fotoURL || 'https://via.placeholder.com/150'}
        alt="Foto de perfil"
        className="rounded-circle mb-3 perfil-img"
      />

      <p><strong>Nombre:</strong> {usuario.nombre}</p>
      <p><strong>Apellido:</strong> {usuario.apellido}</p>
      <p><strong>Email:</strong> {usuario.email}</p>
      <p><strong>País:</strong> {usuario.pais}</p>

      {/* <CambiarPassword usuario={usuario} /> */}

      <hr />
      {/* <button className="btn btn-danger mt-3" onClick={onLogout}>
        Cerrar sesión
      </button> */}
    </section>
  );
};

export default PerfilUsuario;
