// src/App.jsx
import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, useNavigate } from 'react-router-dom';
import Sidebar from './components/Sidebar';
import Footer from './components/Footer';
import RegistroForm from './components/RegistroForm';
import LoginForm from './components/LoginForm';
import PerfilUsuario from './components/PerfilUsuario';
import PerfilAdmin from './components/PerfilAdmin';
import Categorias from './components/Categorias';
import Header from './components/Header';
import Principal from './components/Principal';
import EditarPerfil from './components/EditarPerfil';
import CambiarPassword from './components/CambiarPassword';
import AgregarCompetidor from './components/AgregarCompetidor';
import { ref, get } from 'firebase/database';
import { database } from './firebase/firebase';
import Competidores from './components/Competidores';
import Usuarios from './components/Usuarios';
import MinutoAMinuto from './components/MinutoAMinuto';
{/*import Talleres from './components/Talleres';*/}
import Control from './components/Control';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap/dist/js/bootstrap.bundle.min.js';
import Calificaciones from './components/Calificaciones';
import CalificacionesDetalle from './components/CalificacionesDetalle';


const App = () => {
  const [usuarioLogueado, setUsuarioLogueado] = useState(null);
  const [adminLogueado, setAdminLogueado] = useState(null);

  const handleLoginUsuario = async (user) => {
    try {
      const userRef = ref(database, `usuarios/${user.uid}`);
      const snapshot = await get(userRef);
      if (snapshot.exists()) {
        const userData = snapshot.val();
        setUsuarioLogueado({ uid: user.uid, email: user.email, ...userData });
        setAdminLogueado(null);
      } else {
        alert('Usuario no encontrado en la base de datos.');
      }
    } catch (error) {
      console.error('Error al obtener datos del usuario:', error);
      alert('Error al obtener datos del usuario.');
    }
  };

  const handleLoginAdmin = (admin) => {
    setAdminLogueado(admin);
    setUsuarioLogueado(null);
  };

  const handleLogout = () => {
    setUsuarioLogueado(null);
    setAdminLogueado(null);
    // Si deseas redirigir al cerrar sesión, puedes usar navigate('/'), pero necesitarías pasarlo por props o usar useNavigate aquí también.
  };

  return (
    <Router>
      <Sidebar
        usuario={usuarioLogueado}
        admin={adminLogueado}
        onLogout={handleLogout}
      />
      <Header />
      <Routes>
        <Route path="/" element={<Principal />} />
        <Route path="/registro" element={<RegistroForm />} />
        <Route
          path="/acceder"
          element={
            <LoginForm
              onLogin={handleLoginUsuario}
              onLoginAdmin={handleLoginAdmin}
            />
          }
        />
        <Route
          path="/perfil"
          element={
            usuarioLogueado ? (
              <PerfilUsuario usuario={usuarioLogueado} onLogout={handleLogout} />
            ) : (
              <Principal />
            )
          }
        />
        <Route
          path="/editarPerfil"
          element={usuarioLogueado ? <EditarPerfil usuario={usuarioLogueado} /> : <Principal />}
        />
        <Route
          path="/cambiarPassword"
          element={usuarioLogueado ? <CambiarPassword usuario={usuarioLogueado} /> : <Principal />}
        />
        <Route
          path="/competencia"
          element={usuarioLogueado ? <AgregarCompetidor /> : <Principal />}
        />
        <Route
          path="/admin"
          element={adminLogueado ? <PerfilAdmin admin={adminLogueado} onLogout={handleLogout} /> : <Principal />}
        />
        <Route
          path="/categorias"
          element={adminLogueado ? <Categorias admin={adminLogueado} /> : <Principal />}
        />
        <Route
          path="/competidores"
          element={adminLogueado ? <Competidores /> : <Principal />}
        />
        <Route
          path="/usuarios"
          element={adminLogueado ? <Usuarios /> : <Principal />}
        />
        <Route path="/horario" element={<MinutoAMinuto />} />
        <Route
          path="/control"
          element={adminLogueado ? <Control /> : <Principal />}
        />
        <Route
          path="/calificaciones"
          element={<Calificaciones admin={adminLogueado} />}
        />

        <Route
          path="/calificaciones-detalle/:dia/:categoria/:nombre"
          element={<CalificacionesDetalle /> }
        />

        {/*<Route path="/talleres" element={<Talleres />} />*/}

        {/* Fallback */}
        <Route path="*" element={<Principal />} />
      </Routes>
      <Footer />
    </Router>
  );
};

export default App;
