
import React, { useEffect, useState } from 'react';

import { storage } from '../firebase/firebase';
import {
  ref,
  listAll,
  getDownloadURL
} from 'firebase/storage';

// ========================================
// IMPORTAR IMÁGENES LOCALES
// Compatible con Create React App / Webpack
// ========================================

const importarImagenesLocales = () => {
  const imagenes = require.context(
    '../imagenes',
    false,
    /\.(png|jpe?g|webp|gif)$/i
  );

  return imagenes.keys().map((ruta) => imagenes(ruta));
};

const imagenesLocales = importarImagenesLocales();


// ========================================
// COMPONENTE CARRUSEL
// ========================================

const Carrusel = () => {

  const [imagenes, setImagenes] = useState([]);
  const [cargando, setCargando] = useState(true);

  // ========================================
  // CARGAR IMÁGENES DE FIREBASE Y LOCALES
  // ========================================

  useEffect(() => {

    const cargarImagenes = async () => {

      try {

        // Referencia a la carpeta carrusel de Firebase
        const listRef = ref(storage, 'carrusel/');

        // Obtener lista de imágenes
        const resultado = await listAll(listRef);

        // Obtener URL de cada imagen
        const promesas = resultado.items.map(async (itemRef) => {

          try {

            return await getDownloadURL(itemRef);

          } catch (error) {

            console.warn(
              `No se pudo descargar la imagen: ${itemRef.name}`,
              error
            );

            return null;
          }

        });

        // Esperar todas las descargas
        const imagenesFirebase = (await Promise.all(promesas))
          .filter((url) => url !== null);

        // Combinar imágenes de Firebase y locales
        const todasLasImagenes = [
          ...imagenesFirebase,
          ...imagenesLocales
        ];

        setImagenes(todasLasImagenes);

      } catch (error) {

        console.warn(
          'No se pudieron cargar las imágenes de Firebase. Se utilizarán las imágenes locales.',
          error
        );

        // Si Firebase falla, utilizar imágenes locales
        setImagenes(imagenesLocales);

      } finally {

        setCargando(false);

      }

    };

    cargarImagenes();

  }, []);


  // ========================================
  // DESPLAZAMIENTO AUTOMÁTICO
  // ========================================

  useEffect(() => {

    if (imagenes.length <= 1) return;

    const intervalo = setInterval(() => {

      const carouselElement = document.getElementById(
        'carouselExampleIndicators'
      );

      if (carouselElement) {

        const nextButton = carouselElement.querySelector(
          '.carousel-control-next'
        );

        if (nextButton) {
          nextButton.click();
        }

      }

    }, 3000);

    return () => clearInterval(intervalo);

  }, [imagenes]);


  // ========================================
  // PANTALLA DE CARGA
  // ========================================

  if (cargando) {

    return (
      <div className="text-center p-4">
        <div
          className="spinner-border text-warning"
          role="status"
        >
          <span className="visually-hidden">
            Cargando imágenes...
          </span>
        </div>
      </div>
    );

  }


  // ========================================
  // SI NO HAY IMÁGENES
  // ========================================

  if (imagenes.length === 0) {

    return (
      <div className="text-center p-4">
        No hay imágenes disponibles.
      </div>
    );

  }


  // ========================================
  // MOSTRAR CARRUSEL
  // ========================================

  return (

    <div
      id="carouselExampleIndicators"
      className="carousel slide"
      data-bs-ride="false"
      style={{
        maxWidth: '600px',
        margin: '0 auto'
      }}
    >

      {/* Indicadores */}

      <div className="carousel-indicators">

        {imagenes.map((imagen, index) => (

          <button
            key={index}
            type="button"
            data-bs-target="#carouselExampleIndicators"
            data-bs-slide-to={index}
            className={index === 0 ? 'active' : ''}
            aria-current={index === 0 ? 'true' : undefined}
            aria-label={`Imagen ${index + 1}`}
          />

        ))}

      </div>


      {/* Imágenes */}

      <div className="carousel-inner">

        {imagenes.map((imagen, index) => (

          <div
            key={index}
            className={`carousel-item ${
              index === 0 ? 'active' : ''
            }`}
          >

            <img
              src={imagen}
              className="d-block w-100"
              alt={`Imagen ${index + 1}`}
              style={{
                height: '400px',
                objectFit: 'cover',
                borderRadius: '10px'
              }}
            />

          </div>

        ))}

      </div>


      {/* Botón anterior */}

      <button
        className="carousel-control-prev"
        type="button"
        data-bs-target="#carouselExampleIndicators"
        data-bs-slide="prev"
      >

        <span
          className="carousel-control-prev-icon"
          aria-hidden="true"
        />

        <span className="visually-hidden">
          Anterior
        </span>

      </button>


      {/* Botón siguiente */}

      <button
        className="carousel-control-next"
        type="button"
        data-bs-target="#carouselExampleIndicators"
        data-bs-slide="next"
      >

        <span
          className="carousel-control-next-icon"
          aria-hidden="true"
        />

        <span className="visually-hidden">
          Siguiente
        </span>

      </button>

    </div>

  );

};

export default Carrusel;
