import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { ref, onValue } from 'firebase/database';
import { database } from '../firebase/firebase';

const CalificacionesDetalle = () => {
  const { dia, categoria, nombre } = useParams();
  const [detalle, setDetalle] = useState({});
  const [totalPuntos, setTotalPuntos] = useState(0);
  const [rubricaSel, setRubricaSel] = useState('');

  useEffect(() => {
    const rubricaRef = ref(database, 'adminCompetencia/rubricaSel');
    onValue(rubricaRef, (snapshot) => {
      const data = snapshot.val();
      if (data) setRubricaSel(data);
    });
  }, []);

  useEffect(() => {
    const detalleRef = ref(database, `calificaciones/${dia}/${categoria}/${nombre}`);
    onValue(detalleRef, (snapshot) => {
      const data = snapshot.val() || {};
      setDetalle(data);

      let total = 0;
      Object.values(data).forEach((calif) => {
        const puntos = parseFloat(calif.l_calificacion);
        if (!isNaN(puntos)) total += puntos;
      });
      setTotalPuntos(total);
    });
  }, [dia, categoria, nombre]);

  const normalizarCategoria = (nombre) =>
    nombre.toLowerCase().replace(/[\s\-_.]/g, '');

  const renderRubricaHeaders = () => {
    const cat = normalizarCategoria(categoria);

    if (cat.includes('showcase')) {
      return (
        <>
          <th>Coreografía</th>
          <th>Proy. Escénica</th>
          <th>Técnica/Género</th>
          <th>Dificultad</th>
          <th>Espectáculo</th>
          <th>Efecto</th>
        </>
      );
    } else if (cat.includes('casino')) {
      return (
        <>
          <th>Tiempo</th>
          <th>Técnica</th>
          <th>Musicalidad</th>
          <th>Dificultad</th>
          <th>Originalidad</th>
          <th>Coordinación</th>
          <th>Pres. Visual</th>
          <th>Cubanía</th>
        </>
      );
    } else {
      return (
        <>
          <th>Tiempo</th>
          <th>Técnica/Género</th>
          <th>Coreografía</th>
          <th>Proyección Escénica</th>
          <th>Presencia Visual</th>
          <th>Dificultad</th>
        </>
      );
    }
  };

  const renderRubricaValues = (calif) => {
    const cat = normalizarCategoria(categoria);

    if (cat.includes('showcase')) {
      return (
        <>
          <td>{calif.b_coreografia}</td>
          <td>{calif.c_proyEsc}</td>
          <td>{calif.d_tecnicaGenero}</td>
          <td>{calif.e_dificultad}</td>
          <td>{calif.f_espectaculo}</td>
          <td>{calif.g_efecto}</td>
        </>
      );
    } else if (cat.includes('casino')) {
      return (
        <>
          <td>{calif.b_tiempo}</td>
          <td>{calif.c_tecnica}</td>
          <td>{calif.d_musicalidad}</td>
          <td>{calif.e_dificultad}</td>
          <td>{calif.f_originalidad}</td>
          <td>{calif.g_coordinacion}</td>
          <td>{calif.h_presVisual}</td>
          <td>{calif.i_Cubania}</td>
        </>
      );
    } else {
      return (
        <>
          <td>{calif.b_Tiempo}</td>
          <td>{calif.c_TecnicaGenero}</td>
          <td>{calif.d_Coreografia}</td>
          <td>{calif.e_ProyEsc}</td>
          <td>{calif.f_PresVisual}</td>
          <td>{calif.g_Dificultad}</td>
        </>
      );
    }
  };

  return (
    <div className="container mt-4">
      <h2 className="mb-4 text-center">📊 Detalles de calificación</h2>
      <h4 className="text-center text-success">{nombre}</h4>
      <p className="text-center text-muted">{categoria} - {dia}</p>

      <div className="text-center text-primary fw-bold mb-3">
        TOTAL PUNTOS: {totalPuntos.toFixed(2)}
      </div>

      {Object.keys(detalle).length === 0 ? (
        <p className="text-center text-muted">No hay calificaciones registradas.</p>
      ) : (
        <table className="table table-bordered table-striped mt-3">
          <thead className="table-dark">
            <tr>
              <th>Juez</th>
              {renderRubricaHeaders()}
              <th>Pts</th>
            </tr>
          </thead>
          <tbody>
            {Object.entries(detalle).map(([juez, calif]) => (
              <tr key={juez}>
                <td>{juez}</td>
                {renderRubricaValues(calif)}
                <td><strong>{calif.l_calificacion}</strong></td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
};

export default CalificacionesDetalle;
