import React, { useEffect, useState } from 'react';
import { getDatabase, ref, onValue, remove } from 'firebase/database';
import { FaTrash } from 'react-icons/fa';

const Usuarios = () => {
  const [usuarios, setUsuarios] = useState([]);

  useEffect(() => {
    const db = getDatabase();

    // Obtener usuarios
    const usuariosRef = ref(db, 'usuarios/');
    onValue(usuariosRef, (snapshot) => {
      const data = snapshot.val() || {};
      const usuariosArray = Object.entries(data).map(([key, value]) => ({
        uid: key,
        ...value,
      }));
      setUsuarios(usuariosArray);
    });
  }, []);

  const eliminarUsuario = async (uid) => {
    const db = getDatabase();
    const confirm = window.confirm('¿Seguro que deseas eliminar este usuario?');
    if (!confirm) return;

    try {
      const userRef = ref(db, `usuarios/${uid}`);
      await remove(userRef);
      console.log(`Usuario ${uid} eliminado`);
    } catch (error) {
      console.error('Error al eliminar usuario:', error);
    }
  };

  return (
    <div className="container mt-3">
      <h2>Lista de Usuarios</h2>
      {usuarios.length === 0 && <p className="text-muted">No hay usuarios registrados.</p>}
      {usuarios.map((user) => (
        <div key={user.uid} className="card mb-3">
          <div className="card-body d-flex justify-content-between align-items-start">
            <div>
              <h5 className="card-title">{user.nombre || 'Sin nombre'}</h5>
              <p className="card-text"><strong>Apellido:</strong> {user.apellido || 'N/A'}</p>
              <p className="card-text"><strong>Email:</strong> {user.email || 'N/A'}</p>
              <p className="card-text"><strong>País:</strong> {user.pais || 'N/A'}</p>
            </div>
            <button
              className="btn btn-danger btn-sm"
              onClick={() => eliminarUsuario(user.uid)}
              title="Eliminar usuario"
            >
              <FaTrash />
            </button>
          </div>
        </div>
      ))}
    </div>
  );
};

export default Usuarios;
