// src/components/EditarPerfil.jsx
import React, { useEffect, useState } from 'react';
import { ref as dbRef, get, update } from 'firebase/database';
import { ref as storageRef, uploadBytes, getDownloadURL, deleteObject } from 'firebase/storage'; // 👈 se agregó deleteObject
import { auth, database, storage } from '../firebase/firebase';

const EditarPerfil = () => {
  const [formData, setFormData] = useState({
    nombre: '',
    apellido: '',
    pais: '',
    fotoURL: '',
    fotoPath: '', // 👈 incluir para acceder a la ruta actual
  });
  const [fotoFile, setFotoFile] = useState(null);
  const [paises, setPaises] = useState([]);
  const [loading, setLoading] = useState(true);

  const uid = auth.currentUser?.uid || localStorage.getItem('usuarioUID');

useEffect(() => {
  if (!uid) return;

  const fetchUserData = async () => {
    const snapshot = await get(dbRef(database, `usuarios/${uid}`));
    if (snapshot.exists()) {
      setFormData(snapshot.val());
    }
    setLoading(false);
  };

  fetchUserData();

  fetch('https://restcountries.com/v3.1/all?fields=name')
    .then(res => res.json())
    .then(data => {
      if (!Array.isArray(data)) {
        console.error("La respuesta de países no es un array:", data);
        return;
      }

      const nombres = data
        .map(p => p.name?.common)
        .filter(Boolean)
        .sort((a, b) => a.localeCompare(b));

      setPaises(nombres);
    })
    .catch((error) => {
      console.error("Error al obtener países:", error);
    });
}, [uid]);


  const handleChange = (e) => {
    const { name, value, files } = e.target;
    if (name === 'foto') {
      setFotoFile(files[0]);
    } else {
      setFormData({ ...formData, [name]: value });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      let nuevaFotoURL = formData.fotoURL;
      let nuevoFotoPath = formData.fotoPath;

      // Si se seleccionó nueva foto
      if (fotoFile) {
        // 1. Eliminar la anterior si existe
        if (formData.fotoPath) {
          try {
            const previousRef = storageRef(storage, formData.fotoPath);
            await deleteObject(previousRef);
          } catch (err) {
            console.warn('No se pudo eliminar la foto anterior:', err.message);
          }
        }

        // 2. Subir nueva foto
        nuevoFotoPath = `fotos/${uid}_${fotoFile.name}`;
        const fileRef = storageRef(storage, nuevoFotoPath);
        const snapshot = await uploadBytes(fileRef, fotoFile);
        nuevaFotoURL = await getDownloadURL(snapshot.ref);
      }

      // 3. Actualizar datos
      const datosActualizados = {
        ...formData,
        fotoURL: nuevaFotoURL,
        fotoPath: nuevoFotoPath, // 👈 importante para futuras actualizaciones
      };

      await update(dbRef(database, `usuarios/${uid}`), datosActualizados);
      alert('Perfil actualizado correctamente');
    } catch (error) {
      console.error('Error actualizando perfil:', error);
      alert('Error actualizando perfil: ' + error.message);
    }
  };

  if (!uid) return <p>Usuario no autenticado.</p>;
  if (loading) return <p>Cargando datos...</p>;

  return (
    <section className="p-5 bg-white">
      <h2>Editar Perfil</h2>
      <form className="w-50 mx-auto" onSubmit={handleSubmit}>
        <div className="mb-3 text-center">
          <img
            src={formData.fotoURL || 'https://via.placeholder.com/150'}
            alt="Foto actual"
            className="rounded-circle mb-3"
            width={120}
            height={120}
          />
        </div>
        <div className="mb-3">
          <label className="form-label">Nombre</label>
          <input type="text" className="form-control" name="nombre" value={formData.nombre} onChange={handleChange} required />
        </div>
        <div className="mb-3">
          <label className="form-label">Apellido</label>
          <input type="text" className="form-control" name="apellido" value={formData.apellido} onChange={handleChange} required />
        </div>
        <div className="mb-3">
          <label className="form-label">País</label>
          <select className="form-select" name="pais" value={formData.pais} onChange={handleChange} required>
            <option value="">Seleccione un país</option>
            {paises.map((pais) => (
              <option key={pais} value={pais}>{pais}</option>
            ))}
          </select>
        </div>
        <div className="mb-3">
          <label className="form-label">Nueva foto de perfil</label>
          <input type="file" className="form-control" name="foto" accept="image/*" onChange={handleChange} />
        </div>
        <button type="submit" className="btn btn-success">Guardar cambios</button>
      </form>
    </section>
  );
};

export default EditarPerfil;
