
// src/firebase/firebase.js

import { initializeApp } from 'firebase/app';

import {
  getDatabase,
  connectDatabaseEmulator
} from 'firebase/database';

import {
  getAuth,
  connectAuthEmulator
} from 'firebase/auth';

import {
  getStorage,
  connectStorageEmulator
} from 'firebase/storage';


// =============================================
// CONFIGURACIÓN DEL PROYECTO FIREBASE
// =============================================

const firebaseConfig = {
  apiKey: "AIzaSyA7_9boQaJQ-IUBhDbL1DQ4zNB0UgweM2g",
  authDomain: "tr2025-7f86e.firebaseapp.com",
  databaseURL: "https://tr2025-7f86e-default-rtdb.firebaseio.com",
  projectId: "tr2025-7f86e",
  storageBucket: "tr2025-7f86e.firebasestorage.app",
  // storageBucket: "tr2025-7f86e.appspot.com",
  messagingSenderId: "1019841114004",
  appId: "1:1019841114004:web:fc925898d09d6d0bd4a981",
};


// =============================================
// SELECCIONAR TIPO DE CONEXIÓN
// =============================================

// true  = TRABAJAR LOCALMENTE (Firebase Emulator)
// false = TRABAJAR EN LA NUBE (Firebase real)

const USAR_EMULADOR = true;


// =============================================
// CONFIGURACIÓN DE CONEXIÓN LOCAL
// =============================================

// Coloca aquí la IP de la computadora donde
// se están ejecutando los Firebase Emulators.
//
// Si trabajas desde la misma Mac puedes usar:
// const HOST = '127.0.0.1';
//
// Si accedes desde otros dispositivos de tu red:
// coloca la IP local de tu Mac.

//const HOST = '192.168.1.83';
const HOST = '192.168.0.185'; 
//const HOST = '192.168.1.21'; 


// =============================================
// INICIALIZAR FIREBASE
// =============================================

const app = initializeApp(firebaseConfig);

export const database = getDatabase(app);
export const auth = getAuth(app);
export const storage = getStorage(app);


// =============================================
// CONECTAR A LOS SERVICIOS FIREBASE
// =============================================

if (USAR_EMULADOR) {

  // -------------------------------------------
  // CONEXIÓN LOCAL (FIREBASE EMULATOR)
  // -------------------------------------------

  // Realtime Database Emulator
  connectDatabaseEmulator(database, HOST, 9000);

  // Authentication Emulator
  connectAuthEmulator(
    auth,
    `http://${HOST}:9099`,
    { disableWarnings: true }
  );

  // Storage Emulator
  connectStorageEmulator(storage, HOST, 9199);

  console.log('Firebase conectado a EMULADORES LOCALES');

} else {

  // -------------------------------------------
  // CONEXIÓN A FIREBASE EN LA NUBE
  // -------------------------------------------

  // No se necesita configuración adicional.
  // Firebase utilizará automáticamente los servicios
  // reales definidos en firebaseConfig.

  console.log('Firebase conectado a la NUBE');

}
