import React, { useEffect, useState } from 'react';
import { ref, onValue } from 'firebase/database';
import { database } from '../firebase/firebase';

const MinutoAMinuto = () => {
  const [competidoresPorCategoria, setCompetidoresPorCategoria] = useState({});
  const [categoriasInfo, setCategoriasInfo] = useState({});
  const [nombreASlug, setNombreASlug] = useState({});
  const [horaInicio, setHoraInicio] = useState(null);
  const [selectedRow, setSelectedRow] = useState(null);
  const [activarReloj, setActivarReloj] = useState(false);
  const [horaBase, setHoraBase] = useState(null);
  const [diaSeleccionado, setDiaSeleccionado] = useState(null);
  const [minutosPorCompetidor, setMinutosPorCompetidor] = useState(5); // Valor por defecto

  useEffect(() => {
    const compRef = ref(database, 'competidores/');
    onValue(compRef, (snapshot) => {
      const data = snapshot.val() || {};
      setCompetidoresPorCategoria(data);

      const mapNombreSlug = {};
      Object.entries(data).forEach(([slug, competidores]) => {
        const primerComp = competidores ? Object.values(competidores)[0] : null;
        if (primerComp && primerComp.categoria) {
          mapNombreSlug[primerComp.categoria] = slug;
        }
      });
      setNombreASlug(mapNombreSlug);
    });

    const adminRef = ref(database, 'adminMinutoAMinuto/');
    onValue(adminRef, (snapshot) => {
      const data = snapshot.val() || {};
      if (data.hora) {
        const fecha = new Date(data.hora);
        setHoraInicio(fecha);
        setHoraBase(fecha);
      }
      if (data.selectedRow !== undefined) {
        setSelectedRow(data.selectedRow);
      }
      if (data.activarReloj !== undefined) {
        setActivarReloj(data.activarReloj);
      }
      if (data.dia) {
        setDiaSeleccionado(data.dia.toLowerCase());
      }
      if (data.minutosPorCompetidor !== undefined) {
        setMinutosPorCompetidor(data.minutosPorCompetidor);
      }
    });

    const catRef = ref(database, 'categorias/');
    onValue(catRef, (snapshot) => {
      const data = snapshot.val() || {};
      const mapaCategorias = {};
      Object.entries(data).forEach(([id, cat]) => {
        if (cat.dia && cat.nombre) {
          mapaCategorias[id] = {
            id,
            orden: cat.orden,
            nombre: cat.nombre,
            dia: cat.dia.toLowerCase(),
          };
        }
      });

      setCategoriasInfo(mapaCategorias);
    });
  }, []);

  useEffect(() => {
    if (activarReloj) {
      const interval = setInterval(() => {
        setHoraBase(new Date());
      }, 1000);
      return () => clearInterval(interval);
    } else if (horaInicio) {
      setHoraBase(horaInicio);
    }
  }, [activarReloj, horaInicio]);

  const categoriasOrdenadas = Object.values(categoriasInfo)
    .filter((cat) => cat.dia === diaSeleccionado)
    .sort((a, b) => a.orden - b.orden);

  let listaCompetidores = [];
  categoriasOrdenadas.forEach((cat) => {
    const slug = nombreASlug[cat.nombre];
    const competidores = slug ? competidoresPorCategoria[slug] : null;
    if (competidores) {
      Object.entries(competidores)
        .filter(([_, comp]) => comp.dia && comp.dia.toLowerCase() === diaSeleccionado)
        .forEach(([compId, comp]) => {
          if (comp.orden !== undefined && comp.orden !== null) {
            listaCompetidores.push({ ...comp, categoria: cat.nombre, compId, slug });
          }
        });
    }
  });

  listaCompetidores.sort((a, b) => {
    const ordenCatA = categoriasOrdenadas.find((cat) => cat.nombre === a.categoria)?.orden || 0;
    const ordenCatB = categoriasOrdenadas.find((cat) => cat.nombre === b.categoria)?.orden || 0;
    if (ordenCatA !== ordenCatB) {
      return ordenCatA - ordenCatB;
    }
    return a.orden - b.orden;
  });

  listaCompetidores = listaCompetidores.map((comp, index) => {
    let estatus = 'Espera';
    let color = '#ffc107';
    let horaCompetidor = null;

    if (selectedRow !== null && selectedRow > 0) {
      if (index < selectedRow - 1) {
        estatus = 'Finalizado';
        color = '#dc3545';
      } else if (index === selectedRow - 1) {
        estatus = 'Compitiendo';
        color = '#198754';
        horaCompetidor = horaBase;
      } else {
        estatus = 'Espera';
        color = '#ffc107';
        const minutosAdicionales = (index - (selectedRow - 1)) * minutosPorCompetidor;
        horaCompetidor = horaBase ? new Date(horaBase.getTime() + minutosAdicionales * 60000) : null;
      }
    } else {
      estatus = 'Espera';
      color = '#ffc107';
      horaCompetidor = horaBase ? new Date(horaBase.getTime() + index * minutosPorCompetidor * 60000) : null;
    }

    return {
      ...comp,
      estatus,
      color,
      horaCompetidor,
    };
  });

  const formatearHora = (fecha) =>
    fecha ? fecha.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '--:--';

  return (
    <div className="container mt-4">
      <h2 className="mb-4 text-center">🕒 Minuto a Minuto</h2>

      {categoriasOrdenadas.length === 0 && (
        <p className="text-muted text-center">
          No hay categorías registradas para el día: <strong>{diaSeleccionado}</strong>.
        </p>
      )}

      {listaCompetidores.length === 0 && (
        <p className="text-muted text-center">No hay competidores registrados.</p>
      )}

      {categoriasOrdenadas.map((cat) => (
        <div key={cat.nombre} className="mb-4">
          <h5 className="bg-primary text-white p-2 rounded">
            {cat.orden} - {cat.nombre}
          </h5>
          <table className="table table-striped table-bordered">
            <thead className="table-dark">
              <tr>
                <th style={{ width: '15%' }}>Hora</th>
                <th>Competidor</th>
                <th style={{ width: '15%' }}>Estatus</th>
              </tr>
            </thead>
            <tbody>
              {listaCompetidores
                .filter((c) => c.categoria === cat.nombre)
                .map((comp) => (
                  <tr key={comp.compId}>
                    <td>{comp.estatus === 'Finalizado' ? '--:--' : formatearHora(comp.horaCompetidor)}</td>
                    <td>
                      {comp.nombre || 'Sin nombre'}{' '}
                      <small className="text-muted">({comp.compania || 'Sin compañía'})</small>
                    </td>
                    <td>
                      <span
                        style={{
                          backgroundColor: comp.color,
                          color: comp.color === '#ffc107' ? 'black' : 'white',
                          padding: '4px 8px',
                          borderRadius: '12px',
                          fontWeight: '600',
                          display: 'inline-block',
                          textAlign: 'center',
                          width: '100%',
                          boxShadow: '0 0 6px rgba(0,0,0,0.15)',
                        }}
                      >
                        {comp.estatus}
                      </span>
                    </td>
                  </tr>
                ))}
            </tbody>
          </table>
        </div>
      ))}
    </div>
  );
};

export default MinutoAMinuto;
